INSERT INTO verses_yousafzai (id, ref, book, chapter, verse, text, text_normalized, testament, translation_key, dialect, audio_r2_key, audio_public_url, created_at, updated_at, tags) VALUES
(9101, '2 Kings 5:14', '2 Kings', 5, 14, '&nbsp;نو نعمان د اُردن سيند ته کوز شو، اووۀ ځل يې خپل ځان په کښې غوپه کړو، لکه چې څنګه اليشع ورته فرمائيلى وُو او هغه بلکل روغ شو. د هغۀ څرمن د يو ماشوم په شان روغه شوه.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(9102, '2 Kings 5:15', '2 Kings', 5, 15, '&nbsp;نو هغه د ټولو سړو سره اليشع ته راواپس شو او وې وئيل، ”ګوره، ما ته پته ده چې د بنى اِسرائيلو د خُدائ پاک نه بغېر بل يو خُدائ هم نشته، نو صاحِبه، زما نه تُحفه قبوله کړه.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(9103, '2 Kings 5:16', '2 Kings', 5, 16, '&nbsp;اليشع ورته وفرمائيل، ”زۀ د هغه ژوندى مالِک خُدائ په نوم قسم کوم چې زۀ يې خِدمت کوم چې زۀ به يوه تُحفه هم نۀ قبلوم.“ نو نعمان بيا بيا ورته وئيل چې دا قبوله کړه، خو هغۀ نۀ اخستله.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(9104, '2 Kings 5:17', '2 Kings', 5, 17, '&nbsp;نو نعمان ووئيل، ”کۀ تۀ زما نه تُحفه نۀ قبلوې، نو ما پرېږده چې دوه قچرې په خاورو باندې بار کړم، ځکه چې د نن نه به زۀ د مالِک خُدائ نه بغېر بل يو خُدائ ته هم سوزېدونکې نذرانه يا قربانى پېش نۀ کړم.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(9105, '2 Kings 5:18', '2 Kings', 5, 18, '&nbsp;خو مالِک خُدائ دې ستا خِدمت کوونکى ته دا يوه غلطى معاف کړى، کله چې زما نېک د رِمون عبادتخانې ته د سجدې دپاره ننوځى او هغۀ زما په لاس باندې تکيه وهلې وى او هلته زۀ هم ورسره ټيټ شم، نو چې زۀ کله د رِمون په عبادتخانه کښې ټيټېږم، نو مالِک خُدائ دې ستا خِدمت کوونکے د دې په وجه معاف کړى.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(9106, '2 Kings 5:19', '2 Kings', 5, 19, '&nbsp;اليشع ورته وفرمائيل، ”په خېر لاړ شه.“ او نعمان لاړو. هغۀ لږ شان مزل کړے وو،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(9107, '2 Kings 5:20', '2 Kings', 5, 20, '&nbsp;چې د اليشع نوکر جيحازى د خپل ځان سره ووئيل، ”زما نېک نعمان هم داسې پرېښودو او يو څيز يې هم ترې نه وانۀ خستلو. هغه شامى چې څۀ راوړى وُو نو دۀ له په کار وُو چې هغه يې ترې نه اخستے وے. زۀ په ژوندى مالِک خُدائ قسم کوم چې زۀ به په هغۀ پسې ورمنډه کړم او څۀ نه څۀ به ترې نه واخلم.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(9108, '2 Kings 5:21', '2 Kings', 5, 21, '&nbsp;نو هغه په نعمان پسې روان شو. کله چې نعمان وليدل چې يو سړى ورپسې منډې وهلې، نو هغه د خپلې جنګى ګاډۍ نه ورکوز شو او تپوس يې ترې نه وکړو، ”خېر خو دے؟“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(9109, '2 Kings 5:22', '2 Kings', 5, 22, '&nbsp;جيحازى ورته ووئيل، ”بلکل خېر دے، خو زۀ خپل نېک د دې دپاره راولېږلم چې تا ته ووايم چې دا اوس اوس د پېغمبرانو د قبيلې دوه پېغمبران د غرونو مُلک اِفرائيم نه راورسېدل، نو هغوئ له درې زره د سپينو زرو سيکې او دوه جوړه ښې جامې ورکړه.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(9110, '2 Kings 5:23', '2 Kings', 5, 23, '&nbsp;نعمان ورته ووئيل، ”صاحِبه، د سپينو زرو شپږ زره سيکې واخله.“ هغۀ ورته بيا بيا وئيل، او هغۀ سپين زر په دوو بوجو کښې وتړل او خپلو دوو نوکرانو له يې دوه جوړه ښې جامې ورکړې او د جيحازى نه مخکښې يې ولېږل.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(9111, '2 Kings 5:24', '2 Kings', 5, 24, '&nbsp;کله چې هغوئ هغه غر ته ورسېدل چرته چې اليشع اوسېدو، نو جيحازى هغه دوه بوجۍ واخستلې او کور ته يې يوړې. بيا هغۀ د نعمان نوکران واپس ولېږل.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(9112, '2 Kings 5:25', '2 Kings', 5, 25, '&nbsp;هغه کور ته واپس لاړو او اليشع ترې نه تپوس وکړو، ”تۀ چرته وې؟“ هغۀ ورته ووئيل، ”ستا خِدمت کوونکے هيچرته هم نۀ دے تلے.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(9113, '2 Kings 5:26', '2 Kings', 5, 26, '&nbsp;خو اليشع ورته وفرمائيل، ”زما روح هلته تا سره نۀ وو څۀ چې کله هغه سړے د خپلې جنګى ګاډۍ نه تا له راکوز شو؟ دا وخت د پېسو او جامو، د زيتُونو ونو او د انګورو باغونو، د ګډو او څاروو يا د نوکرانو د قبلولو نۀ دے.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(9114, '2 Kings 5:27', '2 Kings', 5, 27, '&nbsp;نو په دې وجه د نعمان بيمارى به په تا او ستا په اولاد باندې د همېشه دپاره وى.“ کله چې جيحازى لاړو، نو په هغۀ دا بيمارى راغله او د هغۀ څرمن د واورې په شان سپينه شوه.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(9115, '2 Kings 6:1', '2 Kings', 6, 1, '&nbsp;يوه ورځ د اليشع د قبيلې پېغمبران اليشع له ورغلل او هغوئ ورته وفرمائيل چې، ”په کوم ځائ کښې چې مونږ ستا د مشرۍ لاندې اوسيږو نو هغه ځائ زمونږ دپاره ډېر وړوکے دے.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(9116, '2 Kings 6:2', '2 Kings', 6, 2, '&nbsp;مونږ له اجازت راکړه چې د اُردن سيند ته لاړ شُو نو مونږ هر يو به يو يو تير ووهو، نو د اوسېدو دپاره به يو ځائ جوړ کړُو.“ اليشع ورته وفرمائيل، ”لاړ شئ.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(9117, '2 Kings 6:3', '2 Kings', 6, 3, '&nbsp;په هغوئ کښې يو اليشع ته وفرمائيل چې، ”صاحِبه، مونږ سره لاړ شه،“ نو هغه ورسره لاړو،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(9118, '2 Kings 6:4', '2 Kings', 6, 4, '&nbsp;او هغوئ په يو ځائ روان شول. کله چې هغوئ د اُردن سيند ته ورسېدل، نو هغوئ ونې وهل شروع کړل.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(9119, '2 Kings 6:5', '2 Kings', 6, 5, '&nbsp;کله چې هغه يو په کښې يوه ونه وهله، نو ناڅاپه د هغۀ د تبر نه د اوسپنې سر په اوبو کښې وغورزېدو. هغۀ چغه کړه، ”زما نېکه، دا تبر مې د بل چا نه اخستے وو.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(9120, '2 Kings 6:6', '2 Kings', 6, 6, '&nbsp;اليشع ترې نه تپوس وکړو، ”هغه په کوم ځائ کښې ورغورزېدو؟“ نو سړى ورته هغه ځائ وښودلو او اليشع يو لرګے پرې کړو او په اوبو کښې يې وغورزولو، نو د تبر سر راووتلو او د اوبو دپاسه ګرځېدو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(9121, '2 Kings 6:7', '2 Kings', 6, 7, '&nbsp;هغۀ ورته وفرمائيل، ”دا بهر راوباسه.“ او هغه سړى خپل لاس وراوږد کړو او راوايې خستلو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(9122, '2 Kings 6:8', '2 Kings', 6, 8, '&nbsp;د شام بادشاه د اِسرائيل سره په جنګ وو. هغۀ د خپلو آفسرانو سره مشوره وکړه او يو ځائ يې خوښ کړو چې هلته خپلې خېمې ولګوى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(9123, '2 Kings 6:9', '2 Kings', 6, 9, '&nbsp;خو اليشع د اِسرائيل بادشاه له خبردارے ورولېږلو چې هغه ځائ ته ورنزدې نۀ شى، ځکه چې شاميان هلته د حملې دپاره پټ وُو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(9124, '2 Kings 6:10', '2 Kings', 6, 10, '&nbsp;نو د اِسرائيل بادشاه هغه خلقو له خبردارے ورکړو کوم چې په هغه ځائ کښې اوسېدل او د اِسرائيل بادشاه هغوئ د نظر لاندې ساتل. داسې څو څو ځلې وشول.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(9125, '2 Kings 6:11', '2 Kings', 6, 11, '&nbsp;شامى بادشاه په دې باندې ډېر زيات خفه شو، هغۀ خپل آفسران راوغوښتل او تپوس يې ترې نه وکړو، ”ستاسو کوم يو کس د اِسرائيل د بادشاه طرفدارى کوى؟“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(9126, '2 Kings 6:12', '2 Kings', 6, 12, '&nbsp;يو په کښې ووئيل، ”بادشاه سلامت، هيڅ څوک هم نه. اليشع پېغمبر د اِسرائيل بادشاه ته ستا هغه خبرې هم کوى چې تۀ يې د څملاستو په کوټه کښې کوې.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(9127, '2 Kings 6:13', '2 Kings', 6, 13, '&nbsp;بادشاه حُکم وکړو، ”هغه ولټوئ چې کسان ورولېږم او وې نيسم.“ کله چې هغۀ ته ووئيلے شول چې هغه په دوتين کښې دے،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(9128, '2 Kings 6:14', '2 Kings', 6, 14, '&nbsp;نو هغۀ هلته د آسونو او جنګى ګاډو سره يو لوئ لښکر ولېږلو. هغوئ د شپې هغه ښار ته ورسېدل او محاصره يې کړو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(9129, '2 Kings 6:15', '2 Kings', 6, 15, '&nbsp;په ورپسې سحر وختى د اليشع نوکر پاڅېدو، د کور نه بهر لاړو او شامى لښکر او د هغوئ آسونه او جنګى ګاډۍ يې وليدې چې ښار يې محاصره کړے وو. هغه اليشع له واپس لاړو او ورته يې ووئيل، ”زما نېکه، غرق شُو څۀ وکړُو؟“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(9130, '2 Kings 6:16', '2 Kings', 6, 16, '&nbsp;اليشع ورته وفرمائيل، ”مۀ يرېږه، مونږ سره چې څۀ دى نو دا د هغوئ د هر څۀ نه زيات دى.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(9131, '2 Kings 6:17', '2 Kings', 6, 17, '&nbsp;بيا هغۀ دُعا وکړه، ”اے مالِکه خُدايه، د هغۀ سترګې وغړوه نو چې هغه يې وګورى.“ مالِک خُدائ د هغۀ سوال واورېدو او د اليشع نوکر چې بره وکتل نو وې ليدل چې د اليشع نه ګېرچاپېره غر د اور د آسونو او جنګى ګاډو نه ډک وُو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(9132, '2 Kings 6:18', '2 Kings', 6, 18, '&nbsp;کله چې شاميانو حمله وکړه، نو اليشع دُعا وکړه، ”اے مالِکه خُدايه، دا سړى ړاندۀ کړه.“ نو مالِک خُدائ د هغۀ سوال واورېدو او هغوئ يې ړاندۀ کړل.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(9133, '2 Kings 6:19', '2 Kings', 6, 19, '&nbsp;بيا اليشع هغوئ له ورَغلو او ورته يې وفرمائيل، ”تاسو په غلطه لار روان يئ، دا هغه ښار نۀ دے کوم چې تاسو لټوئ. ما پسې راځئ او زۀ به مو هغه سړى له بوځم چې کوم تاسو لټوئ.“ نو هغۀ هغوئ سامريه ته بوتلل.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(9134, '2 Kings 6:20', '2 Kings', 6, 20, '&nbsp;چې څنګه هغوئ ښار ته ورننوتل، نو اليشع دُعا وکړه، ”اے مالِکه خُدايه، د هغوئ سترګې وغړوه چې هغوئ ليدل وکړى.“ نو مالِک خُدائ د هغۀ سوال واورېدو، هغۀ د هغوئ نظر ښۀ کړو او هغوئ وليدل چې هغوئ په سامريه کښې دننه وُو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(9135, '2 Kings 6:21', '2 Kings', 6, 21, '&nbsp;کله چې د اِسرائيل بادشاه شاميان وليدل، نو هغۀ د اليشع نه تپوس وکړو، ”صاحِبه، زۀ هغوئ ووژنم؟ زۀ هغوئ ووژنم څۀ؟“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(9136, '2 Kings 6:22', '2 Kings', 6, 22, '&nbsp;هغۀ ورته وفرمائيل، ”نه، هغه فوجيان مۀ وژنه. کۀ هغوئ په جنګ کښې هم نيولے شوى وے نو هغوئ به دې نۀ وژلے. هغوئ ته روټۍ او اوبۀ کېږده، چې خوراک څښاک وکړى نو واپس دې خپل نېک له لاړ شى.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(9137, '2 Kings 6:23', '2 Kings', 6, 23, '&nbsp;نو د اِسرائيل بادشاه د هغوئ دپاره يوه لويه مېلمستيا وکړه، او چې هغوئ خوراک څښاک وکړو، نو هغوئ يې واپس د شام بادشاه له ولېږل. نو د هغه وخت نه شاميانو د اِسرائيل په مُلک باندې حمله کول پرېښودل.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(9138, '2 Kings 6:24', '2 Kings', 6, 24, '&nbsp;څۀ موده وروستو د شام بادشاه بِن‌حدد د اِسرائيل خِلاف خپل ټول فوج روان کړو او د سامريه ښار يې محاصره کړو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(9139, '2 Kings 6:25', '2 Kings', 6, 25, '&nbsp;نو د دې محاصرې په وجه په ښار کښې د خوراک کمے دومره زيات شو چې د خر يو سر د سپينو زرو په اتيا سيکو باندې خرڅېدو او د تقريباً يو پاو د ګوګوشتکې غل د سپينو زرو په پينځو سيکو باندې خرڅېدل.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(9140, '2 Kings 6:26', '2 Kings', 6, 26, '&nbsp;د اِسرائيل بادشاه د ښار په دېوال باندې ګرځېدو چې يوې ښځې ورته چغه کړه، ”بادشاه سلامت، زما مدد وکړه.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(9141, '2 Kings 6:27', '2 Kings', 6, 27, '&nbsp;هغۀ ورته ووئيل، ”مالِک خُدائ چې ستا مدد نۀ کوى، نو زۀ دې څنګه مدد وکړم؟ ما سره نه د درمند خوراک شته او نۀ د انګورو د لنګرۍ نه مے شته؟', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(9142, '2 Kings 6:28', '2 Kings', 6, 28, '&nbsp;ستا مسئله څۀ ده؟“ هغې ورته ووئيل، ”هغه بله ورځ دې ښځې ما ته ووئيل چې مونږ به زما بچے وخورو او بيا بله ورځ به د هغې بچے وخورو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(9143, '2 Kings 6:29', '2 Kings', 6, 29, '&nbsp;نو مونږ زما زوئ پوخ کړو او ومو خوړو. په ورپسې ورځ ما هغې ته ووئيل چې مونږ به د هغې زوئ وخورو، خو هغې پټ کړو.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(9144, '2 Kings 6:30', '2 Kings', 6, 30, '&nbsp;چې دا يې واورېدل، نو بادشاه د خفګان نه خپلې جامې وشلولې او چې کوم خلق د دېوال سره نزدې وُو نو هغوئ وليدل چې هغۀ د خپلو جامو لاندې د ټاټ جامې اغوستې وې.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(9145, '2 Kings 6:31', '2 Kings', 6, 31, '&nbsp;هغۀ ووئيل، ”کۀ نن ورځ د اليشع سر د بدن نه لرې نۀ شى نو خُدائ پاک دې ما د ورځې د ختمېدو سره ووژنى.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(9146, '2 Kings 6:32', '2 Kings', 6, 32, '&nbsp;نو هغۀ يو پېغام وړونکے ولېږلو چې اليشع راولى. اليشع په کور کښې د يو څو مشرانو سره ملاقات کولو. د بادشاه پېغام وړُونکى د رارسېدو نه مخکښې، اليشع مشرانو ته وفرمائيل، ”هغه قاتِل زما د وژلو دپاره څوک رالېږلے دے. نو چې کله هغه دلته راورسيږى، نو دروازه بنده کړئ او دننه يې مۀ راپرېږدئ. بادشاه به په خپله په هغۀ پسې وى.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(9147, '2 Kings 6:33', '2 Kings', 6, 33, '&nbsp;نو هغۀ لا خبرې ختمې کړې نۀ وې، چې بادشاه راورسېدو او وې وئيل، ”دا مصيبت د مالِک خُدائ نه په مونږ باندې راغلے دے. زۀ دې نور د مالِک خُدائ په طمع کښې ولې پاتې شم؟“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(9148, '2 Kings 7:1', '2 Kings', 7, 1, '&nbsp;بيا اليشع ورته وفرمائيل، ”د مالِک خُدائ کلام ته غوږ ونيسه. مالِک خُدائ داسې فرمائى، سبا دا وخت به د سپينو زرو په يوه سيکه باندې درې کلو ښۀ اوړۀ يا شپږ کلو اوربشې د سامريه د دروازې خولې سره خرڅولے شى.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(9149, '2 Kings 7:2', '2 Kings', 7, 2, '&nbsp;نو د بادشاه خاص آفسر اليشع ته ووئيل، ”کۀ مالِک خُدائ د آسمان نه د غلو دانو د باران دروازې کولاو کړے هم وے، نو دا کار به ونۀ شى.“ اليشع ورته وفرمائيل، ”دا به تۀ په خپلو سترګو ووينې، خو تۀ به ترې نه هيڅ هم ونۀ خورې.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(9150, '2 Kings 7:3', '2 Kings', 7, 3, '&nbsp;په هغه وخت کښې د ښار د دروازې د خولې سره د جذام د بيمارۍ څلور سړى وُو او هغوئ يو بل ته ووئيل، ”مونږ دې تر مرګه پورې دلته ولې ناست يُو؟', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(9151, '2 Kings 7:4', '2 Kings', 7, 4, '&nbsp;ښار ته د ننوتلو فائده نشته، دننه به د لوږې نه مړۀ شُو، خو کۀ مونږ دلته ناست يُو، نو بيا به هم مړۀ شُو. نو راځئ چې د شاميانو کېمپ ته لاړ شُو، کۀ هغوئ زمونږ ژوند بچ کړو، نو ژوندى خو به يُو کۀ نه، خو کۀ ومو وژنى، نو مرو خو هسې هم.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(9152, '2 Kings 7:5', '2 Kings', 7, 5, '&nbsp;نو په ماښامى کښې هغوئ پاڅېدل او د شاميانو کېمپ ته لاړل، خو چې کله هغوئ ورورسېدل، نو هلته هيڅ څوک هم نۀ وُو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(9153, '2 Kings 7:6', '2 Kings', 7, 6, '&nbsp;مالِک خُدائ د شاميانو په فوج باندې د جنګى ګاډو، آسونو او د يو لوئ فوج آوازونه اورولى وُو، نو شاميانو يو بل ته ووئيل، ”د اِسرائيل بادشاه، حِتيان او د مِصر بادشاهان او د هغوئ فوجيان د حملې دپاره په پېسو نيولى دى.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(9154, '2 Kings 7:7', '2 Kings', 7, 7, '&nbsp;نو په هغه ماښام شاميان د خپل ژوند بچ کولو دپاره تښتېدلى وُو، خپلې خېمې، آسونه، خرۀ او خپل کېمپونه يې هم داسې پرېښى وُو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(9155, '2 Kings 7:8', '2 Kings', 7, 8, '&nbsp;کله چې هغه څلور سړى د خېمو غاړې ته ورسېدل، نو هغوئ يوې خېمې ته وردننه شول، هلته چې څۀ وُو نو هغه يې وخوړل او وې څښل، چې کوم سپين زر، سرۀ زر او جامې يې وموندلې نو هغه يې يوړل او پټ يې کړل، هغوئ بيا راغلل، يوې بلې خېمې ته وردننه شول او هم هغه شان يې وکړل.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(9156, '2 Kings 7:9', '2 Kings', 7, 9, '&nbsp;خو بيا هغوئ يو بل ته ووئيل، ”دا کار صحيح نۀ دے. مونږ سره ښۀ زېرے دے او مونږ له دا د ځان سره ساتل نۀ دى په کار. کۀ مونږ تر سبا پورې د دې د وئيلو اِنتظار وکړو، نو سزا به راته مِلاو شى. راځئ چې لاړ شُو او د بادشاه آفسران خبر کړُو.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(9157, '2 Kings 7:10', '2 Kings', 7, 10, '&nbsp;نو هغوئ د شاميانو د کېمپ نه روان شول، واپس سامريه ته لاړل او د دروازو سېنتريانو ته يې آواز وکړو، ”مونږ د شاميانو خېمو ته تلى وُو خو نۀ مو د چا آواز واورېدو او نۀ مو څوک وليدل، آسونه او خرۀ تړلى پاتې وُو او خېمې هم هغه شان روغې ولاړې وې.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(9158, '2 Kings 7:11', '2 Kings', 7, 11, '&nbsp;نو سېنتريانو د دې خبر اِعلان وکړو او دا خبر محل ته ورسېدو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(9159, '2 Kings 7:12', '2 Kings', 7, 12, '&nbsp;خو بادشاه د شپې د کټ نه پاڅېدو او خپلو آفسرانو ته يې ووئيل، ”زۀ به تاسو ته ووايم چې شاميانو زمونږ خِلاف څۀ منصوبه جوړه کړې ده. هغوئ ته زمونږ د قحط پته ده، نو هغوئ ځکه خپلې خېمې پرېښې دى او پټو ته د پټېدو دپاره تلى دى. د هغوئ خيال دا دے چې کله مونږ د خوراک دپاره د ښار نه لاړ شُو، نو هغوئ به مونږ ژوندى ونيسى او ښار به قبضه کړى.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(9160, '2 Kings 7:13', '2 Kings', 7, 13, '&nbsp;د هغۀ يو آفسر ورته ووئيل، ”په دې ښار کښې خلق هسې هم مرګِ حال دى. نو په تاسو کښې دې څۀ کسان پينځۀ آسونه د پاتې شوى آسونو نه خوښ کړئ او لاړ دې شى. کۀ په دوئ څۀ چل وشو، نو پرواه نۀ کوى ځکه کۀ دلته وے نو هم به مونږ سره مړۀ شى. ګنې مونږ ته خو به دا پته ولګى چې څۀ چل دے.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(9161, '2 Kings 7:14', '2 Kings', 7, 14, '&nbsp;نو هغوئ سړى خوښ کړل او بادشاه هغوئ په دوو جنګى ګاډو کښې ولېږل چې لاړ شئ او دا معلوم کړئ چې په شامى فوج باندې څۀ شوى دى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(9162, '2 Kings 7:15', '2 Kings', 7, 15, '&nbsp;چې هغه سړى د اُردن پورې ورپسې لاړل، نو هغوئ په ټوله لار باندې هغه جامې او سامان وليدو چې د شاميانو نه په تېښته کښې پاتې شوے وو. بيا هغوئ راواپس شول او بادشاه يې خبر کړو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(9163, '2 Kings 7:16', '2 Kings', 7, 16, '&nbsp;د سامريه خلق راووتل او د شاميانو خېمې يې لوټ کړې. او لکه چې څنګه مالِک خُدائ فرمائيلى وُو، د سپينو زرو په يوه سيکه باندې درې کلو ښۀ اوړۀ يا شپږ کلو اوربشې خرڅېدلې.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(9164, '2 Kings 7:17', '2 Kings', 7, 17, '&nbsp;نو داسې وشول چې د اِسرائيل بادشاه خپل خاص آفسر ته د ښار د دروازې ذمه وارى په حواله کړې وه. هغه آفسر هلته د خلقو د پښو لاندې شو او مړ شو، لکه څنګه چې اليشع په هغه وخت کښې پېشګوئې کړې وه چې بادشاه هغۀ سره مِلاوېدو له تلے وو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(9165, '2 Kings 7:18', '2 Kings', 7, 18, '&nbsp;اليشع په هغه وخت بادشاه ته فرمائيلى وُو چې سبا دا وخت به په سامريه کښې درې کلو ښۀ غنم يا شپږ کلو اوربشې د سپينو زرو په يوه سيکه باندې خرڅيږى،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(9166, '2 Kings 7:19', '2 Kings', 7, 19, '&nbsp;او آفسر اليشع ته په جواب کښې وئيلى وُو، ”کۀ مالِک خُدائ د آسمان د باران دروازې کولاو کړے هم وے، نو دا کار به ونۀ شى.“ او اليشع ورته فرمائيلى وُو، ”دا به تۀ په خپلو سترګو ووينې، خو تۀ به هيڅ هم ترې نه ونۀ خورې.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(9167, '2 Kings 7:20', '2 Kings', 7, 20, '&nbsp;نو د هغۀ سره هم دغه شان وشول، هغۀ د ښار د دروازې سره د خلقو د پښو لاندې شو او مړ شو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(9168, '2 Kings 8:1', '2 Kings', 8, 1, '&nbsp;نو اليشع هغه ښځې له مشوره ورکړه چې د هغې زوئ يې راژوندے کړے وو، او ورته يې وفرمائيل چې، ”تۀ او ستا خاندان لاړ شئ او په بل ځائ کښې اوسېږئ، ځکه چې مالِک خُدائ فرمائيلى دى چې په دې مُلک کښې به اووۀ کاله قحط وى.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(9169, '2 Kings 8:2', '2 Kings', 8, 2, '&nbsp;نو هغه ښځې هم هغه شان وکړل چې څنګه د خُدائ پاک خِدمتګار مشوره ورکړې وه. هغې خپل خاندان بوتلو او اووۀ کاله د فلستيه په مُلک کښې اوسېدل.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(9170, '2 Kings 8:3', '2 Kings', 8, 3, '&nbsp;د اوؤم کال په ختمېدو، هغه واپس اِسرائيل ته راغله او بادشاه له لاړه چې مِنت ورته وکړى چې خپله زمکه او کور ورته واپس مِلاو شى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(9171, '2 Kings 8:4', '2 Kings', 8, 4, '&nbsp;هغې وليدل چې بادشاه د اليشع نوکر جيحازى سره خبرې کولې، بادشاه غوښتل چې د اليشع په لويو معجزو باندې پوهه شى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(9172, '2 Kings 8:5', '2 Kings', 8, 5, '&nbsp;کله چې جيحازى بادشاه ته وئيل چې اليشع يو مړے راژوندے کړے وو، نو هغه ښځې بادشاه ته عرض وکړو. جيحازى هغۀ ته ووئيل، ”بادشاه سلامت، هغه ښځه دا ده او دا يې زوئ دے چې اليشع راژوندے کړے وو.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(9173, '2 Kings 8:6', '2 Kings', 8, 6, '&nbsp;بادشاه ښځې ته ووئيل چې خپله قيصه بيان کړه، چې څۀ شوى وُو نو هغې ورته بيان کړل. بادشاه يو آفسر راوغوښتو او ورته يې ووئيل چې، ”هغې له خپل هر څۀ واپس ورکړه، سره د هغې د زمکې د اووۀ کالو آمدن.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(9174, '2 Kings 8:7', '2 Kings', 8, 7, '&nbsp;اليشع په هغه وخت دمشق ته لاړو چې د شام بادشاه بِن‌حدد بيمار وو. نو چې بادشاه خبر شو چې اليشع هلته دے،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(9175, '2 Kings 8:8', '2 Kings', 8, 8, '&nbsp;نو هغۀ خپل يو آفسر حِزائيل ته ووئيل، ”هغه پېغمبر له يوه تُحفه يوسه او هغۀ ته ووايه چې د مالِک خُدائ نه تپوس وکړى چې زۀ به د دې بيمارۍ نه ښۀ شم او کۀ نه.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(9176, '2 Kings 8:9', '2 Kings', 8, 9, '&nbsp;نو حِزائيل په څلوېښتو اوښانو باندې د دمشق ښۀ څيزونه بار کړل او اليشع له لاړو. کله چې حِزائيل ورسره مِلاو شو نو ورته يې ووئيل، ”ستا خِدمتګار بِن‌حدد بادشاه زۀ د دې تپوس دپاره رالېږلے يم چې هغه به د خپلې بيمارۍ نه ښۀ شى او کۀ نه.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(9177, '2 Kings 8:10', '2 Kings', 8, 10, '&nbsp;اليشع ورته وفرمائيل، ”مالِک خُدائ ما ته دا څرګنده کړې ده چې هغه به مړ شى، خو هغۀ له لاړ شه او ورته ووايه چې هغه به روغ شى.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(9178, '2 Kings 8:11', '2 Kings', 8, 11, '&nbsp;اليشع ورته نېغ نېغ کتل او سترګې يې ترې نه نۀ اړولې چې خزائيل وشرمېدو نو د خُدائ پاک خِدمتګار په ژړا شروع وکړه.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(9179, '2 Kings 8:12', '2 Kings', 8, 12, '&nbsp;حِزائيل ترې نه تپوس وکړو، ”زما صاحِبه ولې ژاړې؟“ اليشع ورته وفرمائيل، ”ما ته د هغه بدو پته ده چې تۀ به يې د اِسرائيليانو سره کوې، تۀ به د هغوئ قلعې وسوزوې، د هغوئ زلمى به په تُوره ووژنې، د هغوئ بچى به ټوټې ټوټې کړې او د هغوئ د اُميدوارو ښځو خېټې به وشلوې.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(9180, '2 Kings 8:13', '2 Kings', 8, 13, '&nbsp;حِزائيل ورته ووئيل، ”زما په شان يو معمولى انسان دومره غټ کار څنګه کولے شى؟“ اليشع ورته وفرمائيل، ”مالِک خُدائ ما ته ښودلى دى چې تۀ به د شام بادشاه شې.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(9181, '2 Kings 8:14', '2 Kings', 8, 14, '&nbsp;خزائيل بِن‌حدد له لاړو، بِن‌حدد ترې نه تپوس وکړو، ”اليشع څۀ وفرمائيل؟“ حِزائيل ورته ووئيل، ”هغۀ ما ته ووئيل چې تۀ به روغ جوړ شې.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(9182, '2 Kings 8:15', '2 Kings', 8, 15, '&nbsp;خو په ورپسې ورځ خزائيل يوه کمبله واخسته، په اوبو کښې يې لمده کړه او د بادشاه په مخ باندې يې واچوله، ساه يې ورله بنده کړه او مړ شو. او حِزائيل د بِن‌حدد نه پس د شام بادشاه شو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(9183, '2 Kings 8:16', '2 Kings', 8, 16, '&nbsp;د اِسرائيل د بادشاه د اخى‌اب زوئ يورام د بادشاهۍ په پينځم کال، د يهوسفط زوئ يهورام د يهوداه بادشاه شو', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(9184, '2 Kings 8:17', '2 Kings', 8, 17, '&nbsp;چې عُمر يې دوه دېرش کاله وو او هغۀ په يروشلم باندې اتۀ کاله بادشاهى وکړه.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(9185, '2 Kings 8:18', '2 Kings', 8, 18, '&nbsp;هغۀ د اخى‌اب لور وادۀ کړه او د اخى‌اب د خاندان په شان هغه هم د اِسرائيل د بادشاهانو په شان په غلطو لارو روان وو. هغۀ د مالِک خُدائ په نظر کښې بد وکړل،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(9186, '2 Kings 8:19', '2 Kings', 8, 19, '&nbsp;خو مالِک خُدائ نۀ غوښتل چې يهوداه تباه کړى، ځکه چې هغۀ د خپل خِدمت کوونکى داؤد سره لوظ کړے وو چې د هغۀ د اولاد ځلېدونکې بادشاهى به د همېشه دپاره وى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(9187, '2 Kings 8:20', '2 Kings', 8, 20, '&nbsp;د يهورام په بادشاهۍ کښې ادوم د يهوداه خِلاف بغاوت وکړو او يو خپل بادشاه يې جوړ کړو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(9188, '2 Kings 8:21', '2 Kings', 8, 21, '&nbsp;نو يهورام د خپلو ټولو جنګى ګاډو سره صعير ته روان شو، چې هلته ادومى فوجيانو هغوئ محاصره کړل. د شپې هغۀ او د هغۀ د جنګى ګاډو مشرانو محاصره ماته کړه او وتښتېدل او د هغۀ فوجيان خپلو کورونو ته واپس شول.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(9189, '2 Kings 8:22', '2 Kings', 8, 22, '&nbsp;نو د يهوداه ادوم تر اوسه پورې آزاد دے. هم په دې دوران کښې د لِبناه ښار هم بغاوت وکړو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(9190, '2 Kings 8:23', '2 Kings', 8, 23, '&nbsp;يهورام چې نور هر څۀ هم کړى وُو هغه د يهوداه د بادشاهانو د تاريخ په کِتاب کښې ليکلے شوى دى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(9191, '2 Kings 8:24', '2 Kings', 8, 24, '&nbsp;يهورام مړ شو او د داؤد په ښار کښې په شاهى اديره کښې ښخ شو او د هغۀ زوئ اخزياه د هغۀ نه پس بادشاه شو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(9192, '2 Kings 8:25', '2 Kings', 8, 25, '&nbsp;د اِسرائيل بادشاه د اخى‌اب زوئ يورام د بادشاهۍ په دولسم کال، د يهورام زوئ اخزياه د يهوداه بادشاه شو', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(9193, '2 Kings 8:26', '2 Kings', 8, 26, '&nbsp;چې عُمر يې دوويشت کاله وو او هغۀ يو کال په يروشلم باندې بادشاهى وکړه. د هغۀ د مور عتلياه نوم وو، چې د اخى‌اب بادشاه لور او د اِسرائيل بادشاه عُمرى نمسۍ وه.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(9194, '2 Kings 8:27', '2 Kings', 8, 27, '&nbsp;هغه هم د اخى‌اب د خاندان په لار روان وو او هغه څۀ يې کول چې د مالِک خُدائ په نظر کښې بد وُو، لکه څنګه چې د اخى‌اب خاندان کړى وُو، ځکه چې هغه د اخى‌اب د خاندان وو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(9195, '2 Kings 8:28', '2 Kings', 8, 28, '&nbsp;اخزياه بادشاه د اِسرائيل د بادشاه يورام په يو جنګ کښې ملګرتيا وکړه چې دا جنګ د شام د حِزائيل خِلاف وو. فوجونه په رامات‌جِلعاد کښې وجنګېدل او يورام په جنګ کښې زخمى شو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(9196, '2 Kings 8:29', '2 Kings', 8, 29, '&nbsp;هغه د يزرعيل ښار ته راواپس شو چې زخمونه يې روغ شى او اخزياه هلته د مِلاوېدو دپاره ورَغلو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(9197, '2 Kings 9:1', '2 Kings', 9, 1, '&nbsp;په دې دوران کښې اليشع پېغمبر د پېغمبرانو د قبيلې يو کس راوغوښتو او هغۀ ته يې وفرمائيل، ”ملا وتړه او رامات‌جِلعاد ته لاړ شه. د زيتُونو د تېلو دا لوښے ځان سره يوسه،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(9198, '2 Kings 9:2', '2 Kings', 9, 2, '&nbsp;او چې کله تۀ هلته ورسېږې نو د نِمسى نمسے او د يهوسفط زوئ ياهُو ولټوه. او هغه د خپلو ملګرو نه يو کوټې ته بوځه،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(9199, '2 Kings 9:3', '2 Kings', 9, 3, '&nbsp;د لوښى دا تېل د هغۀ په سر باندې واچوه او ورته ووايه چې مالِک خُدائ دا اِعلان کوى چې هغه تا د اِسرائيل بادشاه مقرروى. بيا دروازه کولاو کړه او زر زر وتښته.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(9200, '2 Kings 9:4', '2 Kings', 9, 4, '&nbsp;نو هغه زلمے پېغمبر رامات‌جِلعاد ته لاړو،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]');